static int afs_dynroot_readdir_cells(struct afs_net *net, struct dir_context *ctx)
{
	struct afs_cell *cell;
	loff_t newpos;
	char namebuf[AFSNAMEMAX];
	unsigned int len;
	unsigned int dynroot_ino;
	enum afs_cell_state state;

	_enter("%llu", ctx->pos);

	for (;;) {
		unsigned int ix = ctx->pos >> 1;

		rcu_read_lock();
		cell = idr_get_next(&net->cells_dyn_ino, &ix);
		if (!cell) {
			rcu_read_unlock();
			return 0;
		}

		state = READ_ONCE(cell->state);
		if (state == AFS_CELL_REMOVING || state == AFS_CELL_DEAD) {
			rcu_read_unlock();
			ctx->pos += 2;
			ctx->pos &= ~1;
			continue;
		}

		len = cell->name_len;
		if (len > AFSNAMEMAX - 2)
			len = AFSNAMEMAX - 2;
		memcpy(namebuf, cell->name - 1, len + 1);
		dynroot_ino = cell->dynroot_ino;
		rcu_read_unlock();

		newpos = ix << 1;
		if (newpos > ctx->pos)
			ctx->pos = newpos;

		_debug("pos %llu -> cell %u", ctx->pos, dynroot_ino);

		if ((ctx->pos & 1) == 0) {
			if (!dir_emit(ctx, namebuf + 1, len,
				      dynroot_ino, DT_DIR))
				return 0;
			ctx->pos++;
		}
		if ((ctx->pos & 1) == 1) {
			if (!dir_emit(ctx, namebuf, len + 1,
				      dynroot_ino + 1, DT_DIR))
				return 0;
			ctx->pos++;
		}
	}
	return 0;
}

